VALUES ('PROT-DRIVE-SAFE-1-0-LIVE', 'live', 'DRIVE-SAFE-1.0-live', '{"version":"DRIVE-SAFE-1.0-live","classification":[{"habit":false,"lesion":false,"group":"1","pathway":"Education"},{"habit":false,"lesion":true,"group":"2","pathway":"Clinical lesion pathway"},{"habit":true,"lesion":false,"group":"3","pathway":"Cessation + planned follow-up"},{"habit":true,"lesion":true,"group":"4","pathway":"Clinical lesion pathway + cessation"}],"rules":[],"questions":[{"id":"habits","text":"Current habit","type":"multiple","required":true,"options":["Cigarette","Bidi","Gutkha/tobacco-containing pan masala","Khaini/Zarda/chewing tobacco","Pan with tobacco","Supari/areca nut/pan masala without tobacco","Other tobacco","None"]},{"id":"duration","text":"Duration","type":"single","required":true,"options":["<5 years","5–10 years",">10 years","Not applicable"]},{"id":"frequency","text":"Frequency","type":"frequency","required":true,"options":["Occasional/not every day","1–5 times per day",">5 times per day","Not applicable"]},{"id":"symptoms","text":"Current oral warning symptoms","type":"multiple","required":true,"options":["Non-healing mouth ulcer/wound","White/red patch","Reduced mouth opening","Persistent oral pain/burning","Lump/swelling in mouth or neck","Difficulty/pain while swallowing","None"]},{"id":"symptom_duration","text":"If symptomatic: present for >2 weeks?","type":"single","required":true,"options":["Yes","No","Not applicable"],"when":{"questionId":"symptoms","notEquals":["None"]}},{"id":"awareness","text":"Before today, did you know tobacco/gutkha/supari can increase oral-cancer risk?","type":"yesno","required":true},{"id":"warning_awareness","text":"Did you know a persistent mouth ulcer, red/white patch or other mouth change lasting >2 weeks should be examined?","type":"yesno","required":true},{"id":"previous_screening","text":"Ever had an oral-cancer screening examination?","type":"single","required":true,"options":["Yes","No","Don’t know"]},{"id":"cessation_interest","text":"Would you like help to stop tobacco/areca-nut use?","type":"single","required":true,"options":["Yes","Maybe","No"],"when":{"questionId":"habits","notEquals":["None"]}}]}', 'Approved', 'programme-owner', 'programme-owner', '2026-10-16T00:00:00.000Z');

